async function main() {
  const filePath = '/tmp/…/app.log';
  try {
    const content = await fs.promises.readFile(filePath, 'utf-8');
    const lines = content.split('\n').filter(line => line.trim() !== '');

    const levelCounts: Map<string, number> = new Map();
    const errorComponentCounts: Map<string, number> = new Map();
    const errorMessages: Set<string> = new Set();
    const hourCounts: Map<string, number> = new Map();

    const lineRegex = /^\[(\d{4}-\d{2}-\d{2}) (\d{2}:\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.*)$/;

    for (const line of lines) {
      const match = line.match(lineRegex);
      if (match) {
        const [, , timeStr, level, component, message] = match;
        const [hour] = timeStr.split(':');

        levelCounts.set(level, (levelCounts.get(level) || 0) + 1);
        hourCounts.set(hour, (hourCounts.get(hour) || 0) + 1);

        if (level === 'ERROR') {
          errorComponentCounts.set(component, (errorComponentCounts.get(component) || 0) + 1);
          errorMessages.add(message);
        }
      }
    }

    const sortedLevels = Array.from(levelCounts.entries()).sort((a, b) => a[0].localeCompare(b[0]));
    const levelLines = sortedLevels.map(([l, c]) => `  ${l}: ${c}`);

    let maxErrorComp = '';
    let maxErrorCount = 0;
    for (const [comp, count] of errorComponentCounts.entries()) {
      if (count > maxErrorCount) {
        maxErrorCount = count;
        maxErrorComp = comp;
      }
    }
    const componentLine = maxErrorComp ? `Component with Most Errors: ${maxErrorComp} (${maxErrorCount} errors)` : 'Component with Most Errors: None (0 errors)';

    const sortedMessages = Array.from(errorMessages).sort((a, b) => a.localeCompare(b));
    const messageLines = sortedMessages.map(m => `  - ${m}`);

    let maxHour = '';
    let maxHourCount = 0;
    for (const [hour, count] of hourCounts.entries()) {
      if (count > maxHourCount) {
        maxHourCount = count;
        maxHour = hour;
      }
    }
    const hourLine = maxHour ? `Busiest Hour: ${maxHour}:00 (${maxHourCount} entries)` : 'Busiest Hour: 00:00 (0 entries)';

    let output = '=== Log Analysis ===\n\n';
    output += 'Entries by Level:\n';
    output += levelLines.join('\n') + '\n';
    output += '\n';
    output += componentLine + '\n\n';
    output += 'Unique Error Messages:\n';
    output += messageLines.join('\n') + '\n';
    output += '\n';
    output += hourLine + '\n';

    console.log(output);
  } catch (e) {
    // Silent fail to ensure no extra output on error per constraints
  }
}

