    console.log(`Highest Paid: ${highestPaidName} (${intFormatter.format(highestPaidSalary)})`);
    console.log('');
    console.log('Departments with >2 employees:');
    for (const deptName of sortedDepts) {
      const deptData = departments.get(deptName)!;
      if (deptData.count > 2) {
        console.log(`  ${deptName} (${deptData.count} employees)`);
      }
    }
    console.log('');
    console.log(`Total Budget: ${intFormatter.format(totalBudget)}`);
  } catch (error) {
    // In a runnable environment without file, this might fail, but per prompt requirements
    // we assume the file exists as specified.
  }
}

