import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    public static void main(String[] args) {
        String filePath = "/tmp/…/app.log";
        Pattern pattern = Pattern.compile("^\\[(\\d{4}-\\d{2}-\\d{2}) (\\d{2}:\\d{2}:\\d{2})\\] (\\w+) \\(([^)]+)\\) - (.*)$");

        Map<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> componentErrorCounts = new TreeMap<>();
        Set<String> errorMessages = new TreeSet<>();
        Map<String, Integer> hourCounts = new TreeMap<>();

        try {
            List<String> lines = Files.readAllLines(Paths.get(filePath), StandardCharsets.UTF_8);
            for (String line : lines) {
                line = line.trim();
                if (line.isEmpty()) continue;

                Matcher matcher = pattern.matcher(line);
                if (matcher.matches()) {
                    String level = matcher.group(3);
                    String component = matcher.group(4);
                    String message = matcher.group(5);
                    String time = matcher.group(2);
                    String hourKey = time.substring(0, 2);

                    levelCounts.put(level, levelCounts.getOrDefault(level, 0) + 1);
                    hourCounts.put(hourKey, hourCounts.getOrDefault(hourKey, 0) + 1);

                    if ("ERROR".equalsIgnoreCase(level)) {
                        componentErrorCounts.put(component, componentErrorCounts.getOrDefault(component, 0) + 1);
                        errorMessages.add(message);
                    }
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

        System.out.println("=== Log Analysis ===");
        System.out.println();
        System.out.println("Entries by Level:");
        for (Map.Entry<String, Integer> entry : levelCounts.entrySet()) {
            System.out.println("  " + entry.getKey() + ": " + entry.getValue());
        }
        System.out.println();
        System.out.println("Component with Most Errors: " + getMostErrorComponent(componentErrorCounts) + " (" + getMostErrorCount(componentErrorCounts) + " errors)");
        System.out.println();
        System.out.println("Unique Error Messages:");
        for (String msg : errorMessages) {
            System.out.println("  - " + msg);
        }
        System.out.println();
        System.out.println("Busiest Hour: " + getBusiestHour(hourCounts) + ":00 (" + getBusiestCount(hourCounts) + " entries)");
    }

    private static String getMostErrorComponent(Map<String, Integer> map) {
        if (map.isEmpty()) return "None";
        String maxComp = "";
        int maxCount = -1;
        for (Map.Entry<String, Integer> entry : map.entrySet()) {
            if (entry.getValue() > maxCount) {
                maxCount = entry.getValue();
                maxComp = entry.getKey();
            }
        }
        return maxComp;
    }

    private static int getMostErrorCount(Map<String, Integer> map) {
        if (map.isEmpty()) return 0;
        int max = -1;
        for (int count : map.values()) {
            if (count > max) max = count;
        }
        return max;
    }

    private static String getBusiestHour(Map<String, Integer> map) {
        if (map.isEmpty()) return "00";
        String maxHour = "";
        int maxCount = -1;
        for (Map.Entry<String, Integer> entry : map.entrySet()) {
            if (entry.getValue() > maxCount) {
                maxCount = entry.getValue();
                maxHour = entry.getKey();
            }
        }
        return maxHour;
    }

    private static int getBusiestCount(Map<String, Integer> map) {
        if (map.isEmpty()) return 0;
        int max = -1;
        for (int count : map.values()) {
            if (count > max) max = count;
        }
        return max;
    }
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class Main {
    public static void main(String[] args) {
        Path csvPath = Paths.get("/tmp/…/employees.csv");
        List<String> lines = null;
        try {
            lines = Files.readAllLines(csvPath);
        } catch (IOException e) {
            return;
        }

        if (lines.isEmpty()) return;

        // Skip header
        List<Employee> employees = new ArrayList<>();
        for (int i = 1; i < lines.size(); i++) {
            String line = lines.get(i).trim();
            if (line.isEmpty()) continue;

            String[] parts = line.split(",");
            if (parts.length < 4) continue;

            String name = parts[1].trim();
            String dept = parts[2].trim();
            String salaryStr = parts[3].trim().replace(",", "");
            double salary = 0.0;
            try {
                salary = Double.parseDouble(salaryStr);
            } catch (NumberFormatException e) {
                continue;
            }

            employees.add(new Employee(name, dept, salary));
        }

        // Aggregations
        Map<String, List<Employee>> deptMap = new TreeMap<>();
        for (Employee e : employees) {
            deptMap.computeIfAbsent(e.dept, k -> new ArrayList<>()).add(e);
        }

        Map<String, Double> avgMap = new TreeMap<>();
        for (Map.Entry<String, List<Employee>> entry : deptMap.entrySet()) {
            double sum = 0;
            for (Employee e : entry.getValue()) {
                sum += e.salary;
            }
            avgMap.put(entry.getKey(), sum / entry.getValue().size());
        }

        double maxSalary = -1;
        String maxName = "";
        for (Employee e : employees) {
            if (e.salary > maxSalary) {
                maxSalary = e.salary;
                maxName = e.name;
            }
        }

        double totalBudget = 0;
        for (Employee e : employees) {
            totalBudget += e.salary;
        }

        // Output
        System.out.println("=== Salary Report ===");
        System.out.println();
        System.out.println("Average Salary by Department:");
        for (Map.Entry<String, Double> entry : avgMap.entrySet()) {
            System.out.println("  Department: " + String.format("$%,.2f", entry.getValue()));
        }
        System.out.println();
        System.out.println("Highest Paid: " + maxName + " (" + String.format("$%,d", (long) maxSalary) + ")");
        System.out.println();
        System.out.println("Departments with >2 employees:");
        for (Map.Entry<String, List<Employee>> entry : deptMap.entrySet()) {
            if (entry.getValue().size() > 2) {
                System.out.println("  " + entry.getKey() + " (" + entry.getValue().size() + " employees)");
            }
        }
        System.out.println();
        System.out.println("Total Budget: " + String.format("$%,d", (long) totalBudget));
    }

    static class Employee {
        String name;
        String dept;
        double salary;

        Employee(String name, String dept, double salary) {
            this.name = name;
            this.dept = dept;
            this.salary = salary;
        }
    }
}

