use std::collections::BTreeMap;
use std::fs;
use std::io::Write;

#[derive(Debug, Clone, PartialEq, Eq)]
enum JsonValue {
    String(String),
    Number(f64),
    Bool(bool),
    Null,
    Object(BTreeMap<String, JsonValue>),
    Array(Vec<JsonValue>),
}

fn skip_whitespace(s: &str, i: usize) -> usize {
    while i < s.len() && s.chars().next().unwrap() == ' ' || s.chars().next().unwrap() == '\t' || s.chars().next().unwrap() == '\n' || s.chars().next().unwrap() == '\r' {
        let c = s.chars().nth(i).unwrap();
        if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
            i += 1;
        } else {
            break;
        }
    }
    i
}

fn parse_string(s: &str, i: usize) -> (String, usize) {
    let mut result = String::new();
    let mut chars = s[i..].chars().peekable();
    loop {
        match chars.next() {
            Some('\\') => {
                let next = chars.next().unwrap();
                match next {
                    'n' => result.push('\n'),
                    't' => result.push('\t'),
                    'r' => result.push('\r'),
                    '"' => result.push('"'),
                    '\\' => result.push('\\'),
                    '/' => result.push('/'),
                    'b' => result.push('\x08'),
                    'f' => result.push('\x0c'),
                    'u' => {
                        let mut hex = String::new();
                        for _ in 0..4 {
                            hex.push(chars.next().unwrap());
                        }
                        result.push(char::from_u32(u32::from_str_radix(&hex, 16).unwrap()).unwrap());
                    }
                    c => panic!("Invalid escape character: \\{}", c),
                }
            }
            Some('"') => break,
            Some(c) => result.push(c),
            None => panic!("Unterminated string"),
        }
    }
    (result, i + s[i..].chars().count())
}

fn parse_number(s: &str, i: usize) -> (f64, usize) {
    let mut chars = s[i..].chars().peekable();
    let mut num_str = String::new();
    while let Some(c) = chars.next() {
        if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
            num_str.push(c);
        } else {
            break;
        }
    }
    let num: f64 = num_str.parse().unwrap();
    (num, i + s[i..].chars().take_while(|c| c.is_ascii_digit() || *c == '.' || *c == 'e' || *c == 'E').count())
}

fn parse_value(s: &str, i: usize) -> (JsonValue, usize) {
    let i = skip_whitespace(s, i);
    let c = s[i..].chars().next().unwrap();
    match c {
        '{' => {
            let (obj, end) = parse_object(s, i);
            (JsonValue::Object(obj), end)
        }
        '[' => {
            let (arr, end) = parse_array(s, i);
            (JsonValue::Array(arr), end)
        }
        '"' => {
            let (str_val, end) = parse_string(s, i);
            (JsonValue::String(str_val), end)
        }
        't' => {
            let (end, _) = parse_keyword(s, i, "true");
            (JsonValue::Bool(true), end)
        }
        'f' => {
            let (end, _) = parse_keyword(s, i, "false");
            (JsonValue::Bool(false), end)
        }
        'n' => {
            let (end, _) = parse_keyword(s, i, "null");
            (JsonValue::Null, end)
        }
        '-' | '+' | '0'..='9' | '.' | 'e' | 'E' => {
            let (num, end) = parse_number(s, i);
            (JsonValue::Number(num), end)
        }
        _ => panic!("Unexpected character: {}", c),
    }
}

fn parse_keyword(s: &str, i: usize, keyword: &str) -> (usize, usize) {
    let keyword_bytes = keyword.as_bytes();
    let s_bytes = s[i..].as_bytes();
    if s_bytes.len() < keyword.len() {
        panic!("Unexpected end of input");
    }
    for (j, &byte) in keyword_bytes.iter().enumerate() {
        if s_bytes[j] != byte {
            panic!("Unexpected end of keyword");
        }
    }
    (i + keyword.len(), i + keyword.len())
}

fn parse_object(s: &str, i: usize) -> (BTreeMap<String, JsonValue>, usize) {
    let mut obj = BTreeMap::new();
    let i = skip_whitespace(s, i);
    if i < s.len() && s[i..].chars().next().unwrap() == '}' {
        return (obj, i + 1);
    }
    loop {
        let i = skip_whitespace(s, i);
        let key_str = parse_string(s, i);
        let key = key_str.0;
        let i = skip_whitespace(s, key_str.1);
        if i < s.len() && s[i..].chars().next().unwrap() != ':' {
            panic!("Expected ':'");
        }
        let i = skip_whitespace(s, i);
        if i < s.len() && s[i..].chars().next().unwrap() == '}' {
            return (obj, i + 1);
        }
        let (val, i) = parse_value(s, i);
        obj.insert(key, val);
        let i = skip_whitespace(s, i);
        if i < s.len() && s[i..].chars().next().unwrap() == ',' {
            let i = skip_whitespace(s, i + 1);
        } else {
            break;
        }
    }
}

fn parse_array(s: &str, i: usize) -> (Vec<JsonValue>, usize) {
    let mut arr = Vec::new();
    let i = skip_whitespace(s, i);
    if i < s.len() && s[i..].chars().next().unwrap() == ']' {
        return (arr, i + 1);
    }
    loop {
        let (val, i) = parse_value(s, i);
        arr.push(val);
        let i = skip_whitespace(s, i);
        if i < s.len() && s[i..].chars().next().unwrap() == ',' {
            let i = skip_whitespace(s, i + 1);
        } else {
            break;
        }
    }
    let i = skip_whitespace(s, i);
    if i < s.len() && s[i..].chars().next().unwrap() == ']' {
        (arr, i + 1)
    } else {
        panic!("Expected ']'");
    }
}

fn merge(a: &JsonValue, b: &JsonValue) -> JsonValue {
    match (a, b) {
        (JsonValue::Object(a_obj), JsonValue::Object(b_obj)) => {
            let mut merged = a_obj.clone();
            for (k, v) in b_obj {
                *merged.entry(k).or_insert_with(|| merge(a_obj.get(k).unwrap(), b_obj.get(k).unwrap())) = v;
            }
            JsonValue::Object(merged)
        }
        (JsonValue::Array(a_arr), JsonValue::Array(b_arr)) => {
            let mut merged = a_arr.clone();
            for item in b_arr {
                if !merged.contains(item) {
                    merged.push(item.clone());
                }
            }
            JsonValue::Array(merged)
        }
        (_, _) => b.clone(),
    }
}

fn serialize(value: &JsonValue, indent: usize) -> String {
    match value {
        JsonValue::String(s) => format!("\"{}\"", s),
        JsonValue::Number(n) => n.to_string(),
        JsonValue::Bool(b) => b.to_string(),
        JsonValue::Null => "null".to_string(),
        JsonValue::Object(obj) => {
            if obj.is_empty() {
                "{}".to_string()
            } else {
                let mut parts = Vec::new();
                for (k, v) in obj {
                    let indent_str = "  ".repeat(indent);
                    let inner_indent = "  ".repeat(indent + 1);
                    parts.push(format!("{}\"{}\": {}", indent_str, k, serialize(v, indent + 1)));
                }
                format!("{{\n{}\n{}}}", parts.join(",\n"), indent_str)
            }
        }
        JsonValue::Array(arr) => {
            if arr.is_empty() {
                "[]".to_string()
            } else {
                let mut parts = Vec::new();
                for item in arr {
                    let indent_str = "  ".repeat(indent);
                    let inner_indent = "  ".repeat(indent + 1);
                    parts.push(format!("{}{}", inner_indent, serialize(item, indent + 1)));
                }
                format!("[\n{}\n{}]", parts.join(",\n"), indent_str)
            }
        }
    }
}

