    let json_b = parse_value(&content_b, 0).0;

    let merged = merge(&json_a, &json_b);

    let output = serialize(&merged, 0);
    println!("{}", output);
}

use std::collections::HashMap;
use std::fs;
use std::io::Write;

#[derive(Debug, Clone, PartialEq)]
enum JsonValue {
    String(String),
    Number(f64),
    Bool(bool),
    Null,
    Object(HashMap<String, JsonValue>),
    Array(Vec<JsonValue>),
}

fn skip_whitespace(s: &str, i: usize) -> usize {
    let chars: Vec<char> = s.chars().collect();
    let mut pos = i;
    while pos < chars.len() {
        let c = chars[pos];
        if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
            pos += 1;
        } else {
            break;
        }
    }
    pos
}

fn parse_string(s: &str, i: usize) -> (String, usize) {
    let mut result = String::new();
    let chars: Vec<char> = s[i..].chars().collect();
    let mut pos = 0;
    let mut end = i;

    while pos < chars.len() {
        let c = chars[pos];
        match c {
            '\\' => {
                if pos + 1 < chars.len() {
                    let next = chars[pos + 1];
                    match next {
                        'n' => result.push('\n'),
                        't' => result.push('\t'),
                        'r' => result.push('\r'),
                        '"' => result.push('"'),
                        '\\' => result.push('\\'),
                        '/' => result.push('/'),
                        'b' => result.push('\x08'),
                        'f' => result.push('\x0c'),
                        'u' => {
                            let mut hex = String::new();
                            if pos + 5 < chars.len() {
                                for j in 0..4 {
                                    hex.push(chars[pos + j + 2]);
                                }
                                if let Some(ch) = char::from_u32(u32::from_str_radix(&hex, 16).unwrap()) {
                                    result.push(ch);
                                }
                            }
                        }
                        _ => panic!("Invalid escape character: \\{}", next),
                    }
                    pos += 2;
                } else {
                    panic!("Unterminated string");
                }
            }
            '"' => break,
            _ => {
                result.push(c);
                pos += 1;
            }
        }
    }
    end = i + pos;
    (result, end)
}

fn parse_number(s: &str, i: usize) -> (f64, usize) {
    let chars: Vec<char> = s[i..].chars().collect();
    let mut num_str = String::new();
    let mut pos = 0;

    while pos < chars.len() {
        let c = chars[pos];
        if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
            num_str.push(c);
            pos += 1;
        } else {
            break;
        }
    }

    let num: f64 = num_str.parse().unwrap();
    (num, i + pos)
}

fn parse_value(s: &str, i: usize) -> (JsonValue, usize) {
    let i = skip_whitespace(s, i);
    let chars: Vec<char> = s[i..].chars().collect();
    let c = chars[i];

    match c {
        '{' => {
            let (obj, end) = parse_object(s, i);
            (JsonValue::Object(obj), end)
        }
        '[' => {
            let (arr, end) = parse_array(s, i);
            (JsonValue::Array(arr), end)
        }
        '"' => {
            let (str_val, end) = parse_string(s, i);
            (JsonValue::String(str_val), end)
        }
        't' => {
            let end = i + 4;
            (JsonValue::Bool(true), end)
        }
        'f' => {
            let end = i + 5;
            (JsonValue::Bool(false), end)
        }
        'n' => {
            let end = i + 4;
            (JsonValue::Null, end)
        }
        '-' | '+' | '0'..='9' | '.' | 'e' | 'E' => {
            let (num, end) = parse_number(s, i);
            (JsonValue::Number(num), end)
        }
        _ => panic!("Unexpected character: {}", c),
    }
}

fn parse_object(s: &str, i: usize) -> (HashMap<String, JsonValue>, usize) {
    let chars: Vec<char> = s[i..].chars().collect();
    let mut obj = HashMap::new();
    let mut pos = i;

    pos = skip_whitespace(s, pos);
    if pos < chars.len() && chars[pos] == '}' {
        return (obj, pos + 1);
    }

    loop {
        pos = skip_whitespace(s, pos);
        if pos >= chars.len() || chars[pos] == '}' {
            return (obj, pos + 1);
        }

        let (key_str, key_end) = parse_string(s, pos);
        let key = key_str.0;
        pos = skip_whitespace(s, key_end);

        if pos >= chars.len() || chars[pos] != ':' {
            panic!("Expected ':'");
        }
        pos = skip_whitespace(s, pos);

        if pos >= chars.len() || chars[pos] == '}' {
            return (obj, pos + 1);
        }

        let (val, val_end) = parse_value(s, pos);
        obj.insert(key, val);
        pos = val_end;

        pos = skip_whitespace(s, pos);
        if pos < chars.len() && chars[pos] == ',' {
            pos = skip_whitespace(s, pos + 1);
        } else {
            break;
        }
    }

    pos = skip_whitespace(s, pos);
    if pos < chars.len() && chars[pos] == '}' {
        (obj, pos + 1)
    } else {
        panic!("Expected '}'");
    }
}

fn parse_array(s: &str, i: usize) -> (Vec<JsonValue>, usize) {
    let chars: Vec<char> = s[i..].chars().collect();
    let mut arr = Vec::new();
    let mut pos = i;

    pos = skip_whitespace(s, pos);
    if pos < chars.len() && chars[pos] == ']' {
        return (arr, pos + 1);
    }

    loop {
        if pos >= chars.len() || chars[pos] == ']' {
            break;
        }

        let (val, val_end) = parse_value(s, pos);
        arr.push(val);
        pos = val_end;

        pos = skip_whitespace(s, pos);
        if pos < chars.len() && chars[pos] == ',' {
            pos = skip_whitespace(s, pos + 1);
        } else {
            break;
        }
    }

    pos = skip_whitespace(s, pos);
    if pos < chars.len() && chars[pos] == ']' {
        (arr, pos + 1)
    } else {
        panic!("Expected ']'");
    }
}

fn merge(a: &JsonValue, b: &JsonValue) -> JsonValue {
    match (a, b) {
        (JsonValue::Object(a_obj), JsonValue::Object(b_obj)) => {
            let mut merged = a_obj.clone();
            for (k, v) in b_obj {
                if let Some(existing) = merged.get(k) {
                    *merged.entry(k.clone()).or_insert_with(|| merge(existing, v)) = v.clone();
                } else {
                    merged.insert(k.clone(), v.clone());
                }
            }
            JsonValue::Object(merged)
        }
        (JsonValue::Array(a_arr), JsonValue::Array(b_arr)) => {
            let mut merged = a_arr.clone();
            for item in b_arr {
                if !merged.contains(item) {
                    merged.push(item.clone());
                }
            }
            JsonValue::Array(merged)
        }
        (_, _) => b.clone(),
    }
}

fn serialize(value: &JsonValue, indent: usize) -> String {
    let indent_str = "  ".repeat(indent);
    let inner_indent = "  ".repeat(indent + 1);

    match value {
        JsonValue::String(s) => format!("\"{}\"", s),
        JsonValue::Number(n) => n.to_string(),
        JsonValue::Bool(b) => b.to_string(),
        JsonValue::Null => "null".to_string(),
        JsonValue::Object(obj) => {
            if obj.is_empty() {
                "{}".to_string()
            } else {
                let mut parts = Vec::new();
                let mut sorted_keys: Vec<_> = obj.keys().cloned().collect();
                sorted_keys.sort();
                for k in sorted_keys {
                    let v = &obj[&k];
                    parts.push(format!("{}\"{}\": {}", inner_indent, k, serialize(v, indent + 1)));
                }
                format!("{{\n{}\n{}}}", parts.join(",\n"), indent_str)
            }
        }
        JsonValue::Array(arr) => {
            if arr.is_empty() {
                "[]".to_string()
            } else {
                let mut parts = Vec::new();
                for item in arr {
                    parts.push(format!("{}{}", inner_indent, serialize(item, indent + 1)));
                }
                format!("[\n{}\n{}]", parts.join(",\n"), indent_str)
            }
        }
    }
}

fn main() {
    let path_a = "/tmp/…/config_a.json";
    let path_b = "/tmp/…/config_b.json";

    let content_a = fs::read_to_string(path_a).expect("Failed to read config_a.json");
    let content_b = fs::read_to_string(path_b).expect("Failed to read config_b.json");

    let json_a = parse_value(&content_a, 0).0;
    let json_b = parse_value(&content_b, 0).0;

    let merged = merge(&json_a, &json_b);

    let output = serialize(&merged, 0);
    println!("{}", output);
}

