func formatMoney(value: Double, decimals: Int, prefix: String = "$") -> String {
    let s = String(format: "%.\(decimals)f", value)
    let parts = s.components(separatedBy: ".")
    var integerPart = String(parts[0])
    var fractionalPart = ""
    if parts.count > 1 {
        fractionalPart = String(parts[1])
    }

    // Insert commas
    var formattedInteger = ""
    for (index, char) in integerPart.reversed().enumerated() {
        if index > 0 && index % 3 == 0 {
            formattedInteger += ","
        }
        formattedInteger += char
    }
    let reversedFormatted = formattedInteger.reversed()

    return "\(prefix)\(reversedFormatted).\(fractionalPart)"
}

func formatMoneyInt(value: Double, prefix: String = "$") -> String {
    let rounded = Int(round(value))
    let s = String(rounded)
    var formatted = ""
    for (index, char) in s.reversed().enumerated() {
        if index > 0 && index % 3 == 0 {
            formatted += ","
        }
        formatted += char
    }
    return "\(prefix)\(formatted.reversed())"
}

