use std::collections::HashMap;

fn main() {
    let path = "/tmp/…/employees.csv";
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Error reading file: {}", e);
            return;
        }
    };

    let mut employees: Vec<(String, String, f64)> = Vec::new();
    let lines: Vec<&str> = content.lines().collect();

    if lines.is_empty() {
        return;
    }

    for (i, line) in lines.iter().enumerate() {
        if i == 0 {
            continue; // Skip header
        }
        if line.trim().is_empty() {
            continue;
        }

        let parts: Vec<&str> = line.split(',').collect();
        if parts.len() < 4 {
            continue;
        }

        let dept = parts[2].trim().to_string();
        let name = parts[1].trim().to_string();
        let salary_str = parts[3].trim().to_string();
        let salary: f64 = salary_str.replace(',', "").parse().unwrap_or(0.0);

        employees.push((name, dept, salary));
    }

    let mut dept_salaries: HashMap<String, Vec<f64>> = HashMap::new();
    let mut dept_counts: HashMap<String, u32> = HashMap::new();
    let mut total_budget: f64 = 0.0;
    let mut max_salary: f64 = -1.0;
    let mut max_name: String = String::new();

    for (name, dept, salary) in employees {
        total_budget += salary;
        dept_salaries
            .entry(dept.clone())
            .or_insert_with(Vec::new)
            .push(salary);
        *dept_counts.entry(dept.clone()).or_insert(0) += 1;

        if salary > max_salary {
            max_salary = salary;
            max_name = name;
        }
    }

    // Sort departments alphabetically
    let mut sorted_depts: Vec<String> = dept_salaries.keys().cloned().collect();
    sorted_depts.sort();

    let mut depts_with_count: Vec<(String, u32)> = dept_counts
        .iter()
        .filter(|(_, &c)| c > 2)
        .map(|(k, v)| (k.clone(), *v))
        .collect();
    depts_with_count.sort_by(|a, b| a.0.cmp(&b.0));

    // Helper to format number with commas
    fn format_with_commas(s: &str) -> String {
        let mut result = String::new();
        let mut count = 0;
        let chars: Vec<char> = s.chars().rev().collect();
        for c in chars {
            if count > 0 && count % 3 == 0 {
                result.push(',');
            }
            result.push(c);
            count += 1;
        }
        result.chars().rev().collect()
    }

    // Helper to format currency with decimals
    fn format_currency(val: f64, decimals: usize) -> String {
        let s = format!("{:.prec$}", val, prec = decimals);
        if let Some(pos) = s.find('.') {
            let (int_part, dec_part) = s.split_at(pos);
            let int_formatted = format_with_commas(int_part);
            format!("{}.{}", int_formatted, &s[pos + 1..])
        } else {
            format_with_commas(&s)
        }
    }

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for dept in &sorted_depts {
        let salaries = dept_salaries.get(dept).unwrap();
        let avg = salaries.iter().sum::<f64>() / salaries.len() as f64;
        let avg_str = format_currency(avg, 2);
        println!("  Department: {} {}", dept, avg_str);
    }
    println!();
    println!("Highest Paid: {} ({})", max_name, format_with_commas(&format!("{}", max_salary.round())));
    println!();
    println!("Departments with >2 employees:");
    for (dept, count) in &depts_with_count {
        println!("  {} ({})", dept, count);
    }
    println!();
    println!("Total Budget: {}", format_with_commas(&format!("{}", total_budget.round())));
}

