import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class Main {
    public static void main(String[] args) {
        String pathA = "/tmp/…/config_a.json";
        String pathB = "/tmp/…/config_b.json";

        try {
            String contentA = new String(Files.readAllBytes(Paths.get(pathA)), StandardCharsets.UTF_8);
            String contentB = new String(Files.readAllBytes(Paths.get(pathB)), StandardCharsets.UTF_8);

            JsonParser parserA = new JsonParser(contentA);
            JsonParser parserB = new JsonParser(contentB);

            Object objA = parserA.parse();
            Object objB = parserB.parse();

            Object merged = merge(objA, objB);

            System.out.print(serialize(merged, 0));
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    private static Object merge(Object a, Object b) {
        if (a == null) return b;
        if (b == null) return a;

        if (a instanceof Map && b instanceof Map) {
            Map<String, Object> mapA = (Map<String, Object>) a;
            Map<String, Object> mapB = (Map<String, Object>) b;
            Map<String, Object> merged = new HashMap<>();
            merged.putAll(mapA);
            for (Map.Entry<String, Object> entry : mapB.entrySet()) {
                String key = entry.getKey();
                Object val = entry.getValue();
                if (merged.containsKey(key)) {
                    merged.put(key, merge(merged.get(key), val));
                } else {
                    merged.put(key, val);
                }
            }
            return merged;
        }

        if (a instanceof List && b instanceof List) {
            List<Object> listA = (List<Object>) a;
            List<Object> listB = (List<Object>) b;
            List<Object> merged = new ArrayList<>();
            merged.addAll(listA);
            for (Object item : listB) {
                if (!merged.contains(item)) {
                    merged.add(item);
                }
            }
            return merged;
        }

        return b;
    }

    private static String serialize(Object obj, int indent) {
        if (obj == null) {
            return "null";
        }
        if (obj instanceof String) {
            return "\"" + escape((String) obj) + "\"";
        }
        if (obj instanceof Boolean || obj instanceof Number) {
            return obj.toString();
        }
        if (obj instanceof Map) {
            Map<String, Object> map = (Map<String, Object>) obj;
            List<String> keys = new ArrayList<>(map.keySet());
            Collections.sort(keys);
            StringBuilder sb = new StringBuilder();
            sb.append("{\n");
            String ind = indent("  ", indent + 1);
            String indEnd = indent("  ", indent);
            for (int i = 0; i < keys.size(); i++) {
                String k = keys.get(i);
                sb.append(ind).append(k).append(": ").append(serialize(map.get(k), indent + 1));
                if (i < keys.size() - 1) {
                    sb.append(",\n");
                } else {
                    sb.append("\n");
                }
            }
            sb.append(indEnd).append("}\n");
            return sb.toString();
        }
        if (obj instanceof List) {
            List<Object> list = (List<Object>) obj;
            StringBuilder sb = new StringBuilder();
            sb.append("[\n");
            String ind = indent("  ", indent + 1);
            String indEnd = indent("  ", indent);
            for (int i = 0; i < list.size(); i++) {
                sb.append(ind).append(serialize(list.get(i), indent + 1));
                if (i < list.size() - 1) {
                    sb.append(",\n");
                } else {
                    sb.append("\n");
                }
            }
            sb.append(indEnd).append("]\n");
            return sb.toString();
        }
        return "";
    }

    private static String indent(String s, int count) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < count; i++) {
            sb.append(s);
        }
        return sb.toString();
    }

    private static String escape(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '"') sb.append("\\\"");
            else if (c == '\\') sb.append("\\\\");
            else if (c == '\n') sb.append("\\n");
            else if (c == '\r') sb.append("\\r");
            else if (c == '\t') sb.append("\\t");
            else if (c == '\b') sb.append("\\b");
            else if (c == '\f') sb.append("\\f");
            else sb.append(c);
        }
        return sb.toString();
    }

    static class JsonParser {
        private final String json;
        private int pos = 0;

        public JsonParser(String json) {
            this.json = json;
        }

        public Object parse() {
            skipWhitespace();
            return readValue();
        }

        private void skipWhitespace() {
            while (pos < json.length() && Character.isWhitespace(json.charAt(pos))) {
                pos++;
            }
        }

        private char peek() {
            if (pos >= json.length()) return ' ';
            return json.charAt(pos);
        }

        private char nextChar() {
            if (pos >= json.length()) return ' ';
            return json.charAt(pos++);
        }

        private boolean isDigitOrSign(char c) {
            return Character.isDigit(c) || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-';
        }

        private Object readValue() {
            skipWhitespace();
            char c = peek();
            if (c == '{') return readObject();
            if (c == '[') return readArray();
            if (c == '"') return readString();
            if (c == '-' || Character.isDigit(c)) return readNumber();
            if (c == 't') return readBoolean(true);
            if (c == 'f') return readBoolean(false);
            if (c == 'n') return readNull();
            throw new RuntimeException("Unexpected character: " + c);
        }

        private Object readObject() {
            skipWhitespace();
            nextChar(); // consume '{'
            Map<String, Object> map = new HashMap<>();
            while (true) {
                skipWhitespace();
                String key = readString();
                skipWhitespace();
                nextChar(); // consume ':'
                skipWhitespace();
                Object value = readValue();
                map.put(key, value);
                skipWhitespace();
                char c = peek();
                if (c == '}') break;
                if (c == ',') nextChar();
            }
            return map;
        }

        private Object readArray() {
            skipWhitespace();
            nextChar(); // consume '['
            List<Object> list = new ArrayList<>();
            while (true) {
                skipWhitespace();
                char c = peek();
                if (c == ']') break;
                Object value = readValue();
                list.add(value);
                skipWhitespace();
                c = peek();
                if (c == ']') break;
                if (c == ',') nextChar();
            }
            return list;
        }

        private Object readString() {
            skipWhitespace();
            nextChar(); // consume '"'
            StringBuilder sb = new StringBuilder();
            while (true) {
                char c = nextChar();
                if (c == '"') break;
                if (c == '\\') {
                    char next = nextChar();
                    if (next == '"') sb.append('"');
                    else if (next == '\\') sb.append('\\');
                    else if (next == '/') sb.append('/');
                    else if (next == 'b') sb.append('\b');
                    else if (next == 'f') sb.append('\f');
                    else if (next == 'n') sb.append('\n');
                    else if (next == 'r') sb.append('\r');
                    else if (next == 't') sb.append('\t');
                    else if (next == 'u') {
                        String hex = "";
                        for (int i = 0; i < 4; i++) {
                            hex += nextChar();
                        }
                        sb.append((char) Integer.parseInt(hex, 16));
                    } else {
                        sb.append(next);
                    }
                } else {
                    sb.append(c);
                }
            }
            return sb.toString();
        }

        private Object readNumber() {
            skipWhitespace();
            StringBuilder sb = new StringBuilder();
            while (pos < json.length() && isDigitOrSign(json.charAt(pos))) {
                sb.append(json.charAt(pos++));
            }
            return Double.parseDouble(sb.toString());
        }

        private Object readNull() {
            nextChar(); // 'n'
            nextChar(); // 'u'
            nextChar(); // 'l'
            nextChar(); // 'l'
            return null;
        }

        private Object readBoolean(boolean value) {
            nextChar(); // 't' or 'f'
            nextChar();
            nextChar();
            nextChar();
            return value;
        }
    }
}

