static bool json_eq(JsonValue *a, JsonValue *b) {
    if (a->type != b->type) return false;
    if (a->type == JSON_NULL) return true;
    if (a->type == JSON_BOOL) return a->bool_val == b->bool_val;
    if (a->type == JSON_NUM) return a->num_val == b->num_val;
    if (a->type == JSON_STR) return strcmp(a->str_val, b->str_val) == 0;
    if (a->type == JSON_OBJ) {
        if (a->obj.count != b->obj.count) return false;
        for (int i = 0; i < a->obj.count; i++) {
            // Find matching key in b
            bool found = false;
            for (int j = 0; j < b->obj.count; j++) {
                if (strcmp(a->obj.pairs[i].key, b->obj.pairs[j].key) == 0) {
                    if (!json_eq(a->obj.pairs[i].value, b->obj.pairs[j].value)) return false;
                    found = true;
                    break;
                }
            }
            if (!found) return false;
        }
        return true;
    }
    if (a->type == JSON_ARR) {
        if (a->arr.count != b->arr.count) return false;
        for (int i = 0; i < a->arr.count; i++) {
            if (!json_eq(a->arr.items[i], b->arr.items[i])) return false;
        }
        return true;
    }
    return false;
}

static void sort_keys(JsonValue *obj) {
    if (obj->type != JSON_OBJ) return;
    // Bubble sort or qsort. qsort is better.
    qsort(obj->obj.pairs, obj->obj.count, sizeof(JsonPair), 
          [](const void *a, const void *b) {
              return strcmp(((const JsonPair*)a)->key, ((const JsonPair*)b)->key);
          });
}

static JsonValue *merge(JsonValue *a, JsonValue *b) {
    if (!a) return b;
    if (!b) return a;
    if (a->type != b->type) {
        // Type mismatch: B overrides A (Scalar logic fallback)
        return b;
    }
    if (a->type == JSON_OBJ) {
        JsonValue *res = calloc(1, sizeof(JsonValue));
        res->type = JSON_OBJ;
        res->obj.pairs = malloc(sizeof(JsonPair) * (a->obj.count + b->obj.count + 1));
        res->obj.count = 0;
        res->obj.capacity = a->obj.count + b->obj.count + 1;

        // Add A's pairs
        for (int i = 0; i < a->obj.count; i++) {
            res->obj.pairs[res->obj.count] = a->obj.pairs[i];
            res->obj.count++;
            if (res->obj.count > res->obj.capacity) res->obj.capacity *= 2;
        }
        // Add B's pairs
        for (int i = 0; i < b->obj.count; i++) {
            bool found = false;
            for (int j = 0; j < res->obj.count; j++) {
                if (strcmp(res->obj.pairs[j].key, b->obj.pairs[i].key) == 0) {
                    found = true;
                    break;
                }
            }
            if (found) {
                // Recursive merge
                res->obj.pairs[j].value = merge(res->obj.pairs[j].value, b->obj.pairs[i].value);
                if (!res->obj.pairs[j].value) { // Cleanup
                    free(res->obj.pairs);
                    free(res);
                    return NULL;
                }
            } else {
                // Add new
                res->obj.pairs[res->obj.count] = b->obj.pairs[i];
                res->obj.count++;
                if (res->obj.count > res->obj.capacity) res->obj.capacity *= 2;
            }
        }
        sort_keys(res);
        return res;
    }
    if (a->type == JSON_ARR) {
        JsonValue *res = calloc(1, sizeof(JsonValue));
        res->type = JSON_ARR;
        res->arr.items = malloc(sizeof(JsonValue*) * (a->arr.count + b->arr.count + 1));
        res->arr.count = 0;
        res->arr.capacity = a->arr.count + b->arr.count + 1;

        // Add A's items
        for (int i = 0; i < a->arr.count; i++) {
            res->arr.items[res->arr.count] = a->arr.items[i];
            res->arr.count++;
            if (res->arr.count > res->arr.capacity) res->arr.capacity *= 2;
        }
        // Add B's items (if not duplicate)
        for (int i = 0; i < b->arr.count; i++) {
            bool found = false;
            for (int j = 0; j < res->arr.count; j++) {
                if (json_eq(res->arr.items[j], b->arr.items[i])) {
