            }
        }
        return res;
    }
    // Scalars
    return b;
}

static void free_json(JsonValue *v) {
    if (!v) return;
    if (v->type == JSON_OBJ) {
        for (int i = 0; i < v->obj.count; i++) {
            free(v->obj.pairs[i].key);
            free_json(v->obj.pairs[i].value);
        }
        free(v->obj.pairs);
    } else if (v->type == JSON_ARR) {
        for (int i = 0; i < v->arr.count; i++) {
            free_json(v->arr.items[i]);
        }
        free(v->arr.items);
    } else if (v->type == JSON_STR) {
        free(v->str_val);
    }
    free(v);
}

static void print_json(JsonValue *v, int indent) {
    char *sp = malloc(indent * 2 + 1);
    for (int i = 0; i < indent; i++) sp[i*2] = ' ';
    sp[indent*2] = '\0';

    if (v->type == JSON_NULL) { printf("null"); }
    else if (v->type == JSON_BOOL) { printf("%s", v->bool_val ? "true" : "false"); }
    else if (v->type == JSON_NUM) { printf("%g", v->num_val); }
    else if (v->type == JSON_STR) { printf("\"%s\"", v->str_val); }
    else if (v->type == JSON_OBJ) {
        printf("{\n");
        if (v->obj.count > 0) {
            for (int i = 0; i < v->obj.count; i++) {
                printf("%s  \"%s\": ", sp, v->obj.pairs[i].key);
                print_json(v->obj.pairs[i].value, indent + 1);
                if (i < v->obj.count - 1) printf(",");
                printf("\n");
            }
        }
        printf("%s}", sp);
    } else if (v->type == JSON_ARR) {
        printf("[\n");
        if (v->arr.count > 0) {
            for (int i = 0; i < v->arr.count; i++) {
                printf("%s  ", sp);
                print_json(v->arr.items[i], indent + 1);
                if (i < v->arr.count - 1) printf(",");
                printf("\n");
            }
        }
        printf("%s]", sp);
    }
    free(sp);
}

