static JsonValue *parse_num(void) {
    char *start = input_buf + input_pos;
    bool neg = false;
    if (peek() == '-') { neg = true; input_pos++; }
    if (!isdigit((unsigned char)peek())) { return NULL; }

    while (isdigit((unsigned char)peek())) input_pos++;
    if (peek() == '.') {
        input_pos++;
        while (isdigit((unsigned char)peek())) input_pos++;
    }
    if (peek() == 'e' || peek() == 'E') {
        input_pos++;
        if (peek() == '+' || peek() == '-') input_pos++;
        while (isdigit((unsigned char)peek())) input_pos++;
    }

    char *end = input_buf + input_pos;
    double num = strtod(start, &end);
    if (neg) num = -num;

    return calloc(1, sizeof(JsonValue));
}

static bool json_eq(JsonValue *a, JsonValue *b) {
