                    found = true;
                    break;
                }
            }
            if (!found) return false;
        }
        return true;
    }
    if (a->type == JSON_ARR) {
        if (a->arr.count != b->arr.count) return false;
        for (int i = 0; i < a->arr.count; i++) {
            if (!json_eq(a->arr.items[i], b->arr.items[i])) return false;
        }
        return true;
    }
    return false;
}

