            }
        }
        sort_keys(res);
        return res;
    }
    if (a->type == JSON_ARR) {
        JsonValue *res = calloc(1, sizeof(JsonValue));
        res->type = JSON_ARR;
        res->arr.items = malloc(sizeof(JsonValue*) * (a->arr.count + b->arr.count + 1));
