import json
import heapq

def main():
    path = "/tmp/…/graph.json"

    with open(path, 'r') as f:
        data = json.load(f)

    nodes = data["nodes"]
    edges = data["edges"]

    # Build adjacency list
    adj = {node: [] for node in nodes}
    for edge in edges:
        u = edge["from"]
        v = edge["to"]
        w = edge["weight"]
        if u in adj and v in adj:
            adj[u].append((v, w))
            adj[v].append((u, w))

    start_node = "A"

    # Initialize distances
    distances = {node: float('inf') for node in nodes}
    if start_node in distances:
        distances[start_node] = 0
    else:
        # If start node is not in nodes list, add it to ensure output requirement
        # Though prompt implies it is present.
        distances[start_node] = 0
        nodes.append(start_node)
        adj[start_node] = []

    # Dijkstra's Algorithm
    pq = [(0, start_node)]
    visited = set()

    while pq:
        dist, node = heapq.heappop(pq)

        if node in visited:
            continue
        visited.add(node)

        if node in adj:
            for neighbor, weight in adj[node]:
                if dist + weight < distances[neighbor]:
                    distances[neighbor] = dist + weight
                    heapq.heappush(pq, (distances[neighbor], neighbor))

    # Output
    print("=== Shortest Paths from A ===")
    print()
    sorted_nodes = sorted(nodes)
    for node in sorted_nodes:
        dist = distances.get(node, float('inf'))
        if dist == float('inf'):
            print(f"A -> {node}: inf")
        else:
            print(f"A -> {node}: {dist}")

