use std::collections::{BTreeMap, HashMap, HashSet};
use std::fs::File;
use std::io::{BufRead, BufReader, Cursor};

fn main() {
    let file_path = "/tmp/…/app.log";

    let mut level_counts: BTreeMap<String, u64> = BTreeMap::new();
    let mut component_errors: HashMap<String, u64> = HashMap::new();
    let mut error_messages: HashSet<String> = HashSet::new();
    let mut hour_counts: HashMap<String, u64> = HashMap::new();

    let reader = match File::open(file_path) {
        Ok(f) => BufReader::new(f),
        Err(_) => BufReader::new(Cursor::new(Vec::new())),
    };

    for line in reader.lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => continue,
        };
        if line.trim().is_empty() {
            continue;
        }

        if !line.starts_with('[') {
            continue;
        }

        let close_bracket = match line.find(']') {
            Some(idx) => idx,
            None => continue,
        };

        let timestamp = &line[..close_bracket];
        let rest = &line[close_bracket + 2..];

        if timestamp.len() < 13 {
            continue;
        }
        let hour = timestamp[11..13].to_string();
        *hour_counts.entry(hour).or_insert(0) += 1;

        let parts: Vec<&str> = rest.splitn(2, " - ").collect();
        if parts.len() < 2 {
            continue;
        }

        let header_part = parts[0];
        let message = parts[1].to_string();

        let header_parts: Vec<&str> = header_part.splitn(2, ' ').collect();
        if header_parts.len() < 2 {
            continue;
        }

        let level = header_parts[0].to_string();
        *level_counts.entry(level).or_insert(0) += 1;

        let component_part = header_parts[1];
        if component_part.starts_with('(') && component_part.ends_with(')') {
            let component = component_part[1..component_part.len() - 1].to_string();
            if level == "ERROR" {
                *component_errors.entry(component).or_insert(0) += 1;
                error_messages.insert(message);
            }
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let mut comp_vec: Vec<(String, u64)> = component_errors.into_iter().collect();
    comp_vec.sort_by(|a, b| {
        if b.1 == a.1 {
            a.0.cmp(&b.0)
        } else {
            b.1.cmp(&a.1)
        }
    });
    if let Some((best_comp, best_count)) = comp_vec.first() {
        println!("Component with Most Errors: {} ({})", best_comp, best_count);
    } else {
        println!("Component with Most Errors: None (0 errors)");
    }

    println!();
    println!("Unique Error Messages:");
    let mut msg_vec: Vec<&String> = error_messages.iter().collect();
    msg_vec.sort();
    for msg in msg_vec {
        println!("  - {}", msg);
    }
    println!();

    let mut hour_vec: Vec<(String, u64)> = hour_counts.into_iter().collect();
    hour_vec.sort_by(|a, b| {
        if b.1 == a.1 {
            a.0.cmp(&b.0)
        } else {
            b.1.cmp(&a.1)
        }
    });
    if let Some((best_hour, best_count)) = hour_vec.first() {
        println!("Busiest Hour: {} ({} entries)", format!("{}:00", best_hour), best_count);
    } else {
        println!("Busiest Hour: 00:00 (0 entries)");
    }
}

