import java.net.URL;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    static class Product {
        String name;
        double price;

        public Product(String name, double price) {
            this.name = name;
            this.price = price;
        }
    }

    public static void main(String[] args) {
        try {
            String urlStr = "http://127.0.0.1:18924/api/products";
            URL url = new URL(urlStr);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");
            conn.setConnectTimeout(5000);
            conn.setReadTimeout(5000);
            conn.connect();

            int code = conn.getResponseCode();
            List<Product> products = new ArrayList<>();

            if (code == 200) {
                try (BufferedReader br = new BufferedReader(new InputStreamReader(conn.getInputStream()))) {
                    StringBuilder response = new StringBuilder();
                    String line;
                    while ((line = br.readLine()) != null) {
                        response.append(line);
                    }
                    String json = response.toString();
                    parseJson(json, products);
                }
            }

            // Filter products where price > 50.00
            List<Product> filtered = new ArrayList<>();
            for (Product p : products) {
                if (p.price > 50.00) {
                    filtered.add(p);
                }
            }

            // Sort filtered products by name ascending
            Collections.sort(filtered, (a, b) -> a.name.compareTo(b.name));

            // Output
            System.out.println("=== Filtered Products (price > $50.00) ===");
            System.out.println();

            double total = 0.0;
            for (Product p : filtered) {
                System.out.printf(Locale.US, "ProductName: $%.2f%n", p.price);
                total += p.price;
            }
            System.out.println();

            System.out.println("Count: " + filtered.size());
            System.out.printf(Locale.US, "Total: $%.2f%n", total);

            conn.disconnect();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static void parseJson(String json, List<Product> products) {
        Pattern objectPattern = Pattern.compile("\\{[^{}]*\\}");
        Matcher matcher = objectPattern.matcher(json);

        Pattern namePattern = Pattern.compile("\"name\":\\s*\"([^\"]*)\"");
        Pattern pricePattern = Pattern.compile("\"price\":\\s*([\\d.]+)");

        while (matcher.find()) {
            String object = matcher.group();

            // Extract name
            Matcher nameMatcher = namePattern.matcher(object);
            String name = "";
            if (nameMatcher.find()) {
                name = nameMatcher.group(1);
            }

            // Extract price
            Matcher priceMatcher = pricePattern.matcher(object);
            double price = 0.0;
            if (priceMatcher.find()) {
                try {
                    price = Double.parseDouble(priceMatcher.group(1));
                } catch (NumberFormatException ex) {
                    // Ignore invalid price
                }
            }

            if (!name.isEmpty()) {
                products.add(new Product(name, price));
            }
        }
    }
}

