import * as fs from 'fs';

interface Edge {
  from: string;
  to: string;
  weight: number;
}

interface Graph {
  nodes: string[];
  edges: Edge[];
}

async function main() {
  const filePath = '/tmp/…/graph.json';

  try {
    const rawData = await fs.promises.readFile(filePath, 'utf-8');
    const graph: Graph = JSON.parse(rawData);

    // Build adjacency list
    const adjList = new Map<string, Map<string, number>>();
    for (const node of graph.nodes) {
      adjList.set(node, new Map());
    }

    for (const edge of graph.edges) {
      const u = edge.from;
      const v = edge.to;
      const w = edge.weight;

      if (!adjList.has(u)) adjList.set(u, new Map());
      if (!adjList.has(v)) adjList.set(v, new Map());

      adjList.get(u)!.set(v, w);
      adjList.get(v)!.set(u, w);
    }

    // Dijkstra's Algorithm
    const startNode = 'A';
    const dists = new Map<string, number>();
    const visited = new Set<string>();

    // Initialize distances
    for (const node of graph.nodes) {
      dists.set(node, Infinity);
    }
    dists.set(startNode, 0);

    while (visited.size < graph.nodes.length) {
      let current = '';
      let minDist = Infinity;

      // Find unvisited node with smallest distance
      for (const [node, d] of dists) {
        if (!visited.has(node) && d < minDist) {
          minDist = d;
          current = node;
        }
      }

      if (current === '' || minDist === Infinity) break;

      visited.add(current);

      const neighbors = adjList.get(current);
      if (neighbors) {
        for (const [neighbor, weight] of neighbors) {
          const newDist = dists.get(current)! + weight;
          if (newDist < dists.get(neighbor)!) {
            dists.set(neighbor, newDist);
          }
        }
      }
    }

    // Output results sorted alphabetically
    const sortedNodes = [...graph.nodes].sort((a, b) => a.localeCompare(b));

    console.log('=== Shortest Paths from A ===');
    console.log('');

    for (const node of sortedNodes) {
      const d = dists.get(node);
      console.log(`A -> ${node}: ${d}`);
    }
  } catch (error) {
    // Silently handle errors to ensure clean output format on success
  }
}

