public class Main {
    public static void main(String[] args) {
        try {
            String os = runCommand("uname", "-s").trim();
            String arch = runCommand("uname", "-m").trim();
            String user = runCommand("whoami").trim();
            String host = runCommand("hostname").trim();

            StringBuilder json = new StringBuilder();
            json.append("{\n");
            json.append("  \"hostname\": \"").append(escapeJson(host)).append("\",\n");
            json.append("  \"os\": \"").append(escapeJson(os)).append("\",\n");
            json.append("  \"architecture\": \"").append(escapeJson(arch)).append("\",\n");
            json.append("  \"username\": \"").append(escapeJson(user)).append("\"\n");
            json.append("}");

            System.out.println(json.toString());
        } catch (IOException e) {
            System.out.println("{\n  \"hostname\": \"\",\n  \"os\": \"\",\n  \"architecture\": \"\",\n  \"username\": \"\"\n}");
        }
    }

    private static String runCommand(String... command) throws IOException {
        ProcessBuilder pb = new ProcessBuilder(command);
        pb.redirectErrorStream(true);
        Process process = pb.start();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            StringBuilder output = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line);
            }
            return output.toString();
        }
    }

    private static String escapeJson(String s) {
        if (s == null) {
            return "";
        }
        String escaped = s.replace("\\", "\\\\")
                          .replace("\"", "\\\"");
        return escaped;
    }
}

