char *my_strdup(const char *s) {
    if (!s) return NULL;
    size_t len = strlen(s) + 1;
    char *p = malloc(len);
    if (p) strcpy(p, s);
    return p;
}

char *trim(char *s) {
    while (isspace((unsigned char)*s)) s++;
    if (*s == 0) return s;
    char *end = s + strlen(s) - 1;
    while (end > s && isspace((unsigned char)*end)) end--;
    *(end + 1) = 0;
    memmove(s, s, (size_t)(end - s + 1));
    return s;
}

char *format_int_comma(int val) {
    if (val < 0) {
        char *neg = malloc(20);
        if (!neg) return NULL;
        sprintf(neg, "-%d", -val);
        return neg;
    }
    char buf[20];
    int len = 0;
    if (val == 0) buf[len++] = '0';
    else {
        int temp = val;
        while (temp > 0) {
            buf[len++] = (temp % 10) + '0';
            temp /= 10;
        }
    }
    buf[len] = '\0';

    char *res = malloc(len + len/3 + 2);
    if (!res) return NULL;

    int k = 0;
    int groups = 0;
    int i = len - 1;
    while (i >= 0) {
        if (groups > 0 && (len - 1 - i) % 3 == 0) {
            res[k++] = ',';
            groups++;
        }
        res[k++] = buf[i--];
    }
    res[k] = '\0';
    return res;
}

char *format_double_money(double val) {
    char buf[64];
    sprintf(buf, "%.2f", val);
    char *dot = strchr(buf, '.');
    if (!dot) return my_strdup(buf);

    int len = strlen(buf);
    int dot_pos = dot - buf;
    char *int_part = malloc(dot_pos + 1);
    if (!int_part) return NULL;
    memcpy(int_part, buf, dot_pos);
    int_part[dot_pos] = '\0';

    char *int_formatted = format_int_comma((int)val);
    if (!int_formatted) { free(int_part); return NULL; }

    char *res = malloc(strlen(int_formatted) + 3);
    if (!res) { free(int_part); free(int_formatted); return NULL; }
    strcpy(res, int_formatted);
    res[strlen(int_formatted)] = '.';
    res[strlen(int_formatted) + 1] = '0';
    res[strlen(int_formatted) + 2] = '\0';

    free(int_part);
    free(int_formatted);
    return res;
}

