    fn walk_directory(current: &Path, base: &Path, visited_dirs: &mut std::collections::HashSet<String>, stats: &mut Vec<FileStats>) {
        let mut entries = match fs::read_dir(current) {
            Ok(e) => e,
            Err(_) => return,
        };

        // Sort entries to ensure deterministic order? Not strictly required but good practice.
        // The prompt says "sorted by relative path", so sorting at the end is enough.

        for entry in entries {
            let entry = match entry {
                Ok(e) => e,
                Err(_) => continue,
            };

            let path = entry.path();
            let metadata = match fs::symlink_metadata(&path) {
                Ok(m) => m,
                Err(_) => continue,
            };

            // Skip symlinks
            if metadata.file_type().is_symlink() {
                continue;
            }

            let is_dir = metadata.file_type().is_dir();

            if is_dir {
                // Check visited
                let rel_path = path.strip_prefix(base)
                    .map(|p| p.to_string_lossy().to_string())
                    .unwrap_or_else(|_| path.to_string_lossy().to_string());
                if visited_dirs.contains(&rel_path) {
                    continue;
                }
                visited_dirs.insert(rel_path.clone());
                walk_directory(&path, base, visited_dirs, stats);
            } else if entry.file_type().is_file() {
                // Process file
                let rel_path = path.strip_prefix(base)
                    .map(|p| p.to_string_lossy().to_string())
                    .unwrap_or_else(|_| path.to_string_lossy().to_string());

                let content = match fs::read(&path) {
                    Ok(c) => c,
                    Err(_) => continue, // Skip unreadable files
                };

                let chars = content.len() as u64;
                let lines = content.iter().filter(|&&b| b == b'\n').count() as u64;

                stats.push(FileStats { path: rel_path, lines, chars });
            }
        }
    }

