    static int[][] multiply(int[][] A, int[][] B) {
        int n = A.length;
        int m = A[0].length;
        int p = B[0].length;
        int[][] C = new int[n][p];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < p; j++) {
                for (int k = 0; k < m; k++) {
                    C[i][j] += A[i][k] * B[k][j];
                }
            }
        }
        return C;
    }

    static int determinant(int[][] mat) {
        int n = mat.length;
        if (n == 1) return mat[0][0];
        if (n == 2) return mat[0][0] * mat[1][1] - mat[0][1] * mat[1][0];

        int det = 0;
        for (int j = 0; j < n; j++) {
            int[][] sub = new int[n - 1][n - 1];
            for (int i = 1; i < n; i++) {
                int idx = 0;
                for (int k = 0; k < n; k++) {
                    if (k == j) continue;
                    sub[i - 1][idx++] = mat[i][k];
                }
            }
            det += ((j % 2 == 0) ? 1 : -1) * mat[0][j] * determinant(sub);
        }
        return det;
    }

    static void printMatrix(int[][] mat) {
        for (int[] row : mat) {
            StringBuilder sb = new StringBuilder();
            sb.append("  ");
            for (int i = 0; i < row.length; i++) {
                if (i > 0) sb.append(" ");
                sb.append(String.format("%4d", row[i]));
