public class Main {
    public static void main(String[] args) {
        String filePath = "/tmp/…/graph.json";
        try {
            String content = new String(Files.readAllBytes(Paths.get(filePath)));

            Set<String> nodes = new HashSet<>();
            Map<String, List<Edge>> adj = new HashMap<>();

            // Parse nodes
            Pattern nodesPattern = Pattern.compile("\"nodes\":\\s*\\[([^\\]]*)\\]");
            Matcher nodesMatcher = nodesPattern.matcher(content);
            if (nodesMatcher.find()) {
                String nodesStr = nodesMatcher.group(1);
                nodesStr = nodesStr.replace("[", "").replace("]", "");
                String[] parts = nodesStr.split("\"");
                for (String p : parts) {
                    String node = p.trim();
                    if (!node.isEmpty()) {
                        nodes.add(node);
                        adj.put(node, new ArrayList<>());
                    }
                }
            }

            // Parse edges
            Pattern edgePattern = Pattern.compile("\"from\":\\s*\"([^\"]+)\"\\s*,\\s*\"to\":\\s*\"([^\"]+)\"\\s*,\\s*\"weight\":\\s*([\\d.]+)");
            Matcher edgesMatcher = edgePattern.matcher(content);
            while (edgesMatcher.find()) {
                String from = edgesMatcher.group(1);
                String to = edgesMatcher.group(2);
                double weight = Double.parseDouble(edgesMatcher.group(3));
                if (adj.containsKey(from) && adj.containsKey(to)) {
                    adj.get(from).add(new Edge(to, weight));
                    adj.get(to).add(new Edge(from, weight));
                }
            }

            // Ensure A is in nodes
            nodes.add("A");
            List<String> sortedNodes = new ArrayList<>(nodes);
            Collections.sort(sortedNodes);

            // Dijkstra
            Map<String, Double> dist = new HashMap<>();
            for (String n : sortedNodes) {
                dist.put(n, Double.POSITIVE_INFINITY);
            }
            dist.put("A", 0.0);

            PriorityQueue<Node> pq = new PriorityQueue<>();
            pq.add(new Node("A", 0.0));
            Set<String> visited = new HashSet<>();

            while (!pq.isEmpty()) {
                Node u = pq.poll();
                if (visited.contains(u.name)) continue;
                visited.add(u.name);

                if (adj.containsKey(u.name)) {
                    for (Edge e : adj.get(u.name)) {
                        if (!visited.contains(e.to)) {
                            double newDist = u.dist + e.weight;
                            if (newDist < dist.get(e.to)) {
                                dist.put(e.to, newDist);
                                pq.add(new Node(e.to, newDist));
                            }
                        }
                    }
                }
            }

            // Output
            System.out.println("=== Shortest Paths from A ===");
            System.out.println();
            for (String node : sortedNodes) {
                double d = dist.get(node);
                if (d == Double.POSITIVE_INFINITY) {
                    System.out.println("A -> " + node + ": Infinity");
                } else {
                    String dStr = getDistStr(d);
                    System.out.println("A -> " + node + ": " + dStr);
                }
            }

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static String getDistStr(double d) {
        if (d == (long) d) {
            return String.valueOf((long) d);
        }
        return String.valueOf(d);
    }

    static class Node implements Comparable<Node> {
        String name;
        double dist;

        Node(String name, double dist) {
            this.name = name;
            this.dist = dist;
        }

        @Override
        public int compareTo(Node o) {
            return Double.compare(this.dist, o.dist);
        }
    }

    static class Edge {
        String to;
        double weight;

        Edge(String to, double weight) {
            this.to = to;
            this.weight = weight;
        }
    }
}

