const determinant = (mat: number[][]): number => {
  const n = mat.length;
  if (n === 1) return mat[0][0];
  if (n === 2) return mat[0][0] * mat[1][1] - mat[0][1] * mat[1][0];
  let det = 0;
  for (let col = 0; col < n; col++) {
    const submat: number[][] = [];
    for (let i = 1; i < n; i++) {
      const row: number[] = [];
      for (let j = 0; j < n; j++) {
        if (j !== col) {
