#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <errno.h>

#define MAX_PATH 4096

typedef struct {
    char *path;
    char *ext;
    int lines;
    size_t bytes;
} FileEntry;

typedef struct {
    FileEntry **entries;
    int count;
    int capacity;
} FileList;

void init_file_list(FileList *list) {
    list->entries = NULL;
    list->count = 0;
    list->capacity = 64;
}

void add_file(FileList *list, const char *path, const char *ext, int lines, size_t bytes) {
    if (list->count >= list->capacity) {
        list->capacity *= 2;
        list->entries = realloc(list->entries, list->capacity * sizeof(FileEntry *));
        if (!list->entries) {
            perror("realloc");
            exit(1);
        }
    }
    FileEntry *entry = malloc(sizeof(FileEntry));
    if (!entry) {
        perror("malloc");
        exit(1);
    }
    entry->path = strdup(path);
    if (!entry->path) {
        perror("strdup path");
        exit(1);
    }
    entry->ext = strdup(ext);
    if (!entry->ext) {
        perror("strdup ext");
        exit(1);
    }
    entry->lines = lines;
    entry->bytes = bytes;
    list->entries[list->count] = entry;
    list->count++;
}

void free_file_list(FileList *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->entries[i]->path);
        free(list->entries[i]->ext);
        free(list->entries[i]);
    }
    free(list->entries);
}

int compare_entries(const void *a, const void *b) {
    const FileEntry *ea = *(const FileEntry **)a;
    const FileEntry *eb = *(const FileEntry **)b;
    int ext_cmp = strcmp(ea->ext, eb->ext);
    if (ext_cmp != 0) return ext_cmp;
    return strcmp(ea->path, eb->path);
}

int count_lines_and_bytes(FILE *fp, int *lines, size_t *bytes) {
    char *buf = malloc(4096);
    if (!buf) {
        perror("malloc buffer");
        return -1;
    }
    *lines = 0;
    *bytes = 0;
    size_t n;
    while ((n = fread(buf, 1, 4096, fp)) > 0) {
        for (size_t i = 0; i < n; i++) {
            if (buf[i] == '\n') {
                (*lines)++;
            }
        }
        (*bytes) += n;
    }
    free(buf);
    return 0;
}

char *get_extension(const char *path) {
    char *last_dot = strrchr(path, '.');
    if (last_dot) {
        return strdup(last_dot);
    } else {
        return strdup("");
    }
}

void walk(const char *base, const char *rel_prefix, FileList *list) {
    DIR *dir = opendir(base);
    if (!dir) {
        perror("opendir");
        return;
    }
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        char full_path[MAX_PATH];
        char new_rel[MAX_PATH];
        if (snprintf(full_path, sizeof(full_path), "%s/%s", base, entry->d_name) >= (int)sizeof(full_path)) {
            perror("snprintf full_path");
            continue;
        }
        if (snprintf(new_rel, sizeof(new_rel), "%s/%s", rel_prefix, entry->d_name) >= (int)sizeof(new_rel)) {
            perror("snprintf new_rel");
            continue;
        }
        struct stat st;
        if (lstat(full_path, &st) == -1) {
            perror("lstat");
            continue;
        }
        if (S_ISLNK(st.st_mode)) {
            continue;
        }
        if (S_ISDIR(st.st_mode)) {
            walk(full_path, new_rel, list);
        } else if (S_ISREG(st.st_mode)) {
            FILE *fp = fopen(full_path, "rb");
            if (fp) {
                int lines = 0;
                size_t bytes = 0;
                if (count_lines_and_bytes(fp, &lines, &bytes) == 0) {
                    char *ext = get_extension(new_rel);
                    add_file(list, new_rel, ext, lines, bytes);
                }
                fclose(fp);
                free(ext);
            }
        }
    }
    closedir(dir);
}

