    int (*C)[3] = (int(*)[3])malloc(3 * sizeof(int[3]));

    if (!A || !B || !C) {
        return 1;
    }

    // Initialize Matrix A
    A[0][0] = 1; A[0][1] = 2; A[0][2] = 3;
    A[1][0] = 4; A[1][1] = 5; A[1][2] = 6;
