struct Product {
    id: u64,
    name: String,
    price: f64,
    category: String,
    stock: u64,
}

fn parse_json(json: &str) -> Vec<Product> {
    let mut products = Vec::new();
    let mut i = 0;

    while i < json.len() {
        if json[i] == '[' {
            i += 1;
            continue;
        }

        if json[i] == ']' {
            break;
        }

        if json[i] == '{' {
            let product = parse_product(json, &mut i);
            products.push(product);

            if i < json.len() && json[i] == ',' {
                i += 1;
            }
        }

        i += 1;
    }

    products
}

fn parse_product(json: &str, pos: &mut usize) -> Product {
    let mut product = Product {
        id: 0,
        name: String::new(),
        price: 0.0,
        category: String::new(),
        stock: 0,
    };

    *pos += 1;

    while *pos < json.len() {
        if json[*pos] == '}' {
            *pos += 1;
            return product;
        }

        while *pos < json.len() && json[*pos].is_whitespace() {
            *pos += 1;
        }

        if *pos >= json.len() {
            break;
        }

        let key = parse_string(json, pos);
        *pos += 1;

        if *pos < json.len() && json[*pos] == ':' {
            *pos += 1;

            if *pos < json.len() && json[*pos] == '"' {
                let value = parse_string(json, pos);
                *pos += 1;

                match key.as_str() {
                    "id" => product.id = value.parse().ok().unwrap_or(0),
                    "name" => product.name = value,
                    "price" => product.price = value.parse().ok().unwrap_or(0.0),
                    "category" => product.category = value,
                    "stock" => product.stock = value.parse().ok().unwrap_or(0),
                    _ => {}
                }
            } else if *pos < json.len() {
                let value = parse_value(json, pos);
                match key.as_str() {
                    "id" => product.id = value.parse().ok().unwrap_or(0),
                    "name" => product.name = value,
                    "price" => product.price = value.parse().ok().unwrap_or(0.0),
                    "category" => product.category = value,
                    "stock" => product.stock = value.parse().ok().unwrap_or(0),
                    _ => {}
                }
            }
        }

        while *pos < json.len() && json[*pos].is_whitespace() {
            *pos += 1;
        }
        if *pos < json.len() && json[*pos] == ',' {
            *pos += 1;
        }
    }

    product
}

fn parse_string(json: &str, pos: &mut usize) -> String {
    let mut result = String::new();
    *pos += 1;

    while *pos < json.len() && json[*pos] != '"' {
        if json[*pos] == '\\' && *pos + 1 < json.len() {
            *pos += 1;
            match json[*pos] {
                'n' => result.push('\n'),
                't' => result.push('\t'),
                'r' => result.push('\r'),
                '"' => result.push('"'),
                '\\' => result.push('\\'),
                _ => result.push(json[*pos]),
            }
        } else {
            result.push(json[*pos]);
        }
        *pos += 1;
    }

    if *pos < json.len() {
        *pos += 1;
    }

    result
}

fn parse_value(json: &str, pos: &mut usize) -> String {
    if json[*pos] == '"' {
        return parse_string(json, pos);
    }

    if json[*pos] == '[' {
        return parse_array(json, pos);
    }

    if json[*pos] == '{' {
        return parse_object(json, pos);
    }

    if json[*pos].is_digit(10) || json[*pos] == '-' {
        let mut num = String::new();
        while *pos < json.len() && json[*pos].is_digit(10) {
            num.push(json[*pos]);
            *pos += 1;
        }
        return num;
    }

    if json[*pos] == 't' || json[*pos] == 'f' || json[*pos] == 'n' || json[*pos] == 'u' {
        let mut word = String::new();
        while *pos < json.len() && json[*pos].is_alphabetic() {
            word.push(json[*pos]);
            *pos += 1;
        }
        return word;
    }

    String::new()
}

fn parse_array(json: &str, pos: &mut usize) -> Vec<String> {
    let mut result = Vec::new();
    *pos += 1;

    while *pos < json.len() {
        if json[*pos] == ']' {
            *pos += 1;
            return result;
        }

        let value = parse_value(json, pos);
        result.push(value);

        while *pos < json.len() && json[*pos].is_whitespace() {
            *pos += 1;
        }
        if *pos < json.len() && json[*pos] == ',' {
            *pos += 1;
        }
    }

    result
}

fn parse_object(json: &str, pos: &mut usize) -> String {
    let mut result = String::new();
    *pos += 1;

    while *pos < json.len() {
        if json[*pos] == '}' {
            *pos += 1;
            return result;
        }

        let key = parse_string(json, pos);
        *pos += 1;

        if *pos < json.len() && json[*pos] == ':' {
            *pos += 1;
            let value = parse_value(json, pos);
            if !value.is_empty() {
                result.push_str(&value);
            }
        }

        while *pos < json.len() && json[*pos].is_whitespace() {
            *pos += 1;
        }
        if *pos < json.len() && json[*pos] == ',' {
            *pos += 1;
        }
    }

    result
}

let A: [[Int]] = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
let B: [[Int]] = [[9, 8, 7], [6, 5, 4], [3, 2, 1]]

func multiply(_ A: [[Int]], _ B: [[Int]]) -> [[Int]] {
    let rowsA = A.count
    let colsA = A[0].count
    let colsB = B[0].count
    var C = [[Int]](repeating: [Int](repeating: 0, count: colsB), count: rowsA)

    for i in 0..<rowsA {
        for j in 0..<colsB {
            var sum = 0
            for k in 0..<colsA {
                sum += A[i][k] * B[k][j]
            }
            C[i][j] = sum
        }
    }
    return C
}

func determinant(_ M: [[Int]]) -> Int {
    let a = M[0][0], b = M[0][1], c = M[0][2]
    let d = M[1][0], e = M[1][1], f = M[1][2]
    let g = M[2][0], h = M[2][1], i = M[2][2]
    return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g)
}

